UPDATE wms_batch_location_balance SET quantity = quantity - #{quantity},
    reserved_quantity = reserved_quantity - #{quantity}, picked_quantity = picked_quantity - #{quantity}
WHERE tenant_id = #{tenant} AND batch_no = #{batch} AND location_id = #{location}
  AND picked_quantity >= #{quantity} AND reserved_quantity >= #{quantity}

UPDATE wms_batch_location_balance SET reserved_quantity = reserved_quantity - #{quantity}
WHERE tenant_id = #{tenant} AND batch_no = #{batch} AND location_id = #{location}
  AND reserved_quantity - picked_quantity >= #{quantity}

