INSERT INTO wms_quality_correction(tenant_id, correction_id, batch_no, quantity, reason, original_inspection_id,
    original_inspection, created_by, created_at)
SELECT #{tenant}, #{id}, #{batch}, #{quantity}, #{reason}, i.inspection_id, row_to_json(i)::text, #{operator}, #{at}
FROM wms_purchase_inspection i WHERE i.tenant_id = #{tenant} AND i.batch_no = #{batch}

