UPDATE wms_batch_location_balance SET quantity = quantity - #{quantity}
WHERE tenant_id = #{tenant} AND batch_no = #{batch} AND location_id = #{location}
  AND reserved_quantity = picked_quantity AND review_quantity = 0 AND quantity - reserved_quantity >= #{quantity}
